from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    # cache: key -> [value, write_time]
    cache = OrderedDict()
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                val, wtime = cache[key]
                if t - wtime >= ttl:
                    # expired, remove
                    del cache[key]
            if key in cache:
                # still present (not expired), update in place
                cache[key] = [value, t]
                cache.move_to_end(key)
            else:
                # need to insert new
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)
        else:
            _, t, key = op
            if key in cache:
                val, wtime = cache[key]
                if t - wtime >= ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(val)
            else:
                results.append(-1)

    return results

